  const [acikFotografIndeksi, setAcikFotografIndeksi] = useState<number | null>(null)
""")
s = rep(s, "                      onPress={() => setBuyukFotograf(a)}\n",
        "                      onPress={() => setAcikFotografIndeksi(fotograflar.indexOf(a))}\n")
# anı kartina onFotografAc
s = rep(s, """                    zamanYazisi={gorecelZaman(ani.olusturmaZamani, t)}
                    ozet={ozetler[ani.id]}
                    onBegen={begeniDegistir}
                    // Yorumlar kartin ICINDE alttan aciliyor; ekranin
                    // tek isi sayaci tazelemek.""", """                    zamanYazisi={gorecelZaman(ani.olusturmaZamani, t)}
                    ozet={ozetler[ani.id]}
                    onBegen={begeniDegistir}
                    onFotografAc={() =>
                      setAcikFotografIndeksi(fotograflar.findIndex((f) => f.id === ani.id))
                    }
                    // Yorumlar kartin ICINDE alttan aciliyor; ekranin
                    // tek isi sayaci tazelemek.""")
# eski modal -> gezgin
